/**
 * Jinx Magician + Vizier: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Magician
 * Wiki: https://wiki.bloodontheclocktower.com/Vizier
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L115). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { GENERIC_REMINDER_ID } from '#lib/core/model/types.ts';
import { abilityState } from '#lib/core/rules/abilities/ability.ts';
import { demonInfo } from '#lib/core/rules/night/evil-info.ts';
import { executionOutcomes } from '#lib/core/rules/day/execution-outcome.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes/jinx-pairs.ts';
import { setupReminders } from '#lib/core/rules/setup/setup-reminders.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './vizier.test-support.ts';

describe('Magician + Vizier jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'magician', 'vizier');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('magician')?.name).toBe('Magician');
		expect(data.byId.get('vizier')?.name).toBe('Vizier');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['magician', 'vizier'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['magician'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['vizier'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: while the Vizier is in play the Magician has no ability, so
	// the evil team learns the truth, and the Vizier's execute now doesn't reach the Magician.
	describe('the Magician has no ability but is immune to the Vizier', () => {
		const ids = ['vizier', 'magician', 'imp', 'chef', 'empath', 'poisoner', 'monk'];
		const script = scriptOf(ids);
		const base = scenario(['vizier', 'magician', 'imp', 'chef', 'empath', 'poisoner', 'monk'], {
			script
		});

		it("is data in the Vizier's rules", () => {
			expect(jinxRulesBetween('vizier', 'magician', committedCharacters())).toEqual({
				noExecuteNow: { player: 'partner' }
			});
		});

		it('takes the Magician ability while the Vizier is in play, even dead', () => {
			// Wiki: "If the Vizier is in play, the Magician has no ability but is immune to the Vizier's
			// ability."
			const state = abilityState(base.game, base.seat('magician'), base.characters);
			expect(state.works).toBe(false);
			expect(state.impairments.map((i) => [i.reason, i.source])).toEqual([
				['no-ability', { characterId: 'vizier', seatId: base.seat('vizier') }]
			]);
			const dead = base.dies('vizier');
			expect(abilityState(dead.game, dead.seat('magician'), dead.characters).works).toBe(false);
			const none = scenario(['magician', 'imp', 'chef', 'empath', 'poisoner'], { script });
			expect(abilityState(none.game, none.seat('magician'), none.characters).works).toBe(true);
		});

		it('so the evil team learns the truth on the first night', () => {
			// Wiki: "If the Vizier is in play, the Magician has no ability but is immune to the Vizier's
			// ability."
			expect(demonInfo(base.game, base.characters)).toMatchObject({
				shownAsMinions: [],
				shownAsDemon: []
			});
			const none = scenario(['magician', 'imp', 'chef', 'empath', 'poisoner'], { script });
			expect(demonInfo(none.game, none.characters).shownAsDemon).toEqual([none.seat('magician')]);
		});

		it('setup suggests No Ability on the Magician', () => {
			const jinxed = setupReminders(base.game, base.characters).filter(
				(r) => r.characterId === GENERIC_REMINDER_ID
			);
			expect(jinxed).toMatchObject([
				{ label: 'No Ability', seatId: base.seat('magician'), timing: 'setup', candidates: [] }
			]);
		});

		it("warns on the Vizier's execute now on the Magician, and not on another player", () => {
			// Wiki: "If the Vizier is in play, the Magician has no ability but is immune to the Vizier's
			// ability."
			const s = base.nominate('chef', 'magician').nominate('empath', 'imp');
			const problem = (on: 'magician' | 'imp') =>
				executionOutcomes(s.game, s.seat(on), s.characters).find((o) => o.kind === 'execute-now')
					?.problem;
			expect(problem('magician')).toBe('jinxed');
			expect(problem('imp')).toBeUndefined();
		});
	});
});
